/**
 * 文档/块目标选择 Composable
 * 封装 selectTargetDocument/selectTargetBlock 逻辑（含加载与状态写入的内部实现）
 */
import { type Ref } from "vue"
import { showMessage } from "siyuan"
import type { TargetDoc } from "@/types/ai"
import * as api from "@/api"
import { getCurrentBlockId } from "@/utils/domUtils"
import { removeFrontmatter } from "../utils"

export interface UseDocumentTargetDeps {
  editTargetDoc: Ref<TargetDoc | null>
  originalContent: Ref<string>
  generatedContent: Ref<string>
  displayedContent: Ref<string>
  /** 清除自定义输入的回调 */
  onClearCustomInput: () => void
}

export function useDocumentTarget(deps: UseDocumentTargetDeps) {
  const {
    editTargetDoc, originalContent, generatedContent,
    displayedContent, onClearCustomInput,
  } = deps

  /** 加载文档内容 */
  const loadDocument = async (
    docId: string,
  ): Promise<{ title: string; content: string } | null> => {
    try {
      const docBlock = await api.getBlockByID(docId)
      if (!docBlock) {
        showMessage("无法获取文档信息", 3000, "error")
        return null
      }
      const docContent = await api.exportMdContent(docId)
      if (!docContent || !docContent.content) {
        showMessage("无法获取文档内容", 3000, "error")
        return null
      }
      return {
        title: docBlock.content || "未命名文档",
        content: docContent.content,
      }
    } catch (error) {
      console.error("加载文档失败:", error)
      showMessage("加载文档失败: " + (error as Error).message, 3000, "error")
      return null
    }
  }

  // 防重入标志：加载进行中忽略重复点击，避免后完成者覆盖状态的竞态
  let isSelecting = false

  /** 设置目标文档状态 */
  const setTargetDocState = (doc: TargetDoc) => {
    editTargetDoc.value = doc
    originalContent.value = doc.content
    generatedContent.value = doc.content
    displayedContent.value = doc.content
    onClearCustomInput()
  }

  /** 加载目标文档 */
  const loadTargetDocument = async (docId: string) => {
    const result = await loadDocument(docId)
    if (!result) return
    const cleanContent = removeFrontmatter(result.content)
    setTargetDocState(
      { id: docId, title: result.title, content: cleanContent, isBlock: false },
    )
  }

  /** 选择目标文档 */
  const selectTargetDocument = async () => {
    if (isSelecting) return
    isSelecting = true
    try {
      const protyle = document.querySelector(
        ".layout__wnd--active .protyle:not(.fn__none)",
      )
      let docId = protyle
        ?.querySelector(".protyle-background")
        ?.getAttribute("data-node-id") || null

      if (!docId) {
        const currentBlockId = getCurrentBlockId()
        if (currentBlockId) {
          docId = await api.getDocIdByBlockId(currentBlockId)
        }
      }

      if (!docId) {
        showMessage("无法获取当前文档，请将光标放在文档中", 2000, "error")
        return
      }

      await loadTargetDocument(docId)
    } catch (error) {
      console.error("选择文档失败:", error)
      showMessage("选择文档失败: " + (error as Error).message, 3000, "error")
    } finally {
      isSelecting = false
    }
  }

  /** 选择当前光标所在的块 */
  const selectTargetBlock = async () => {
    if (isSelecting) return
    isSelecting = true
    try {
      const blockId = getCurrentBlockId()
      if (!blockId) {
        showMessage("无法获取当前块，请将光标放在目标块中", 2000, "error")
        return
      }

      const blockContent = await api.getBlockMarkdown(blockId)
      if (!blockContent) {
        showMessage("无法获取块内容", 2000, "error")
        return
      }

      const blockInfo = await api.getBlockByID(blockId)
      const docTitle = blockInfo?.content || "块内容"

      setTargetDocState(
        { id: blockId, title: docTitle, content: blockContent, isBlock: true },
      )
    } catch (error) {
      console.error("选择块失败:", error)
      showMessage("选择块失败: " + (error as Error).message, 3000, "error")
    } finally {
      isSelecting = false
    }
  }

  return {
    selectTargetDocument,
    selectTargetBlock,
  }
}

/**
 * 编辑操作 Composable
 * 封装 applyEdit/undoEdit/insertSubDocument/copyContent/clearContent 逻辑
 */
import { ref, computed, type Ref } from "vue"
import { showMessage } from "siyuan"
import type { TargetDoc } from "@/types/ai"
import * as api from "@/api"
import { copyToClipboard } from "@/utils/domUtils"
import {
  processContentByType,
  splitMarkdownBlocks,
  convertToSiyuanMarkdown,
} from "../utils"

// ============ 类型 ============

interface EditHistory {
  docId: string
  docTitle: string
  originalContent: string
  timestamp: number
  isBlock?: boolean
  insertedBlockIds?: string[]
}

const MAX_EDIT_HISTORY = 20

export interface UseEditOperationsDeps {
  editTargetDoc: Ref<TargetDoc | null>
  originalContent: Ref<string>
  generatedContent: Ref<string>
  displayedContent: Ref<string>
  errorMessage: Ref<string>
  generationElapsed: Ref<string>
}

// ============ Composable ============

export function useEditOperations(deps: UseEditOperationsDeps) {
  const {
    editTargetDoc, originalContent, generatedContent,
    displayedContent, errorMessage, generationElapsed,
  } = deps

  const isApplying = ref(false)
  const isUndoing = ref(false)
  const isInsertingSubDoc = ref(false)
  const editHistoryStack = ref<EditHistory[]>([])

  const canUndoEdit = computed(() => editHistoryStack.value.length > 0)

  /** 清除内容显示 */
  const clearContent = () => {
    generatedContent.value = ""
    displayedContent.value = ""
    errorMessage.value = ""
    generationElapsed.value = ""
  }

  /** 清除目标文档（含编辑模式状态与内容显示） */
  const clearTargetDocument = () => {
    editTargetDoc.value = null
    originalContent.value = ""
    // editCustomInput is managed externally
    editHistoryStack.value = []
    clearContent()
  }

  /** 复制内容到剪贴板 */
  const copyContent = async () => {
    if (!generatedContent.value) return
    try {
      const siyuanContent = convertToSiyuanMarkdown(generatedContent.value)
      const ok = await copyToClipboard(siyuanContent)
      if (!ok) {
        throw new Error("剪贴板写入失败")
      }
    } catch (error) {
      console.error("复制失败:", error)
      showMessage("复制失败", 2000, "error")
    }
  }

  /** 应用编辑 */
  const applyEdit = async () => {
    if (!editTargetDoc.value) return

    isApplying.value = true
    let insertedBlockIds: string[] = []

    try {
      const siyuanContent = processContentByType(
        generatedContent.value,
        editTargetDoc.value.isBlock ?? false,
      )
      const docId = editTargetDoc.value.id

      if (editTargetDoc.value.isBlock) {
        const blocks = splitMarkdownBlocks(siyuanContent)
        if (blocks.length === 0) {
          throw new Error("生成的内容为空")
        }

        // 第一个块：更新原始块
        const result = await api.updateBlock("markdown", blocks[0], docId)
        if (!result) {
          throw new Error("updateBlock API 返回为空，更新可能未生效")
        }

        // 剩余块：逐个追加
        if (blocks.length > 1) {
          let prevId = docId
          for (let i = 1; i < blocks.length; i++) {
            const insertResult = await api.insertBlock(
              "markdown", blocks[i], undefined, prevId,
            )
            if (!insertResult || insertResult.length === 0) {
              throw new Error("insertBlock API 返回为空，追加内容可能未生效")
            }
            // insertBlock 返回 IResdoOperations[]（数组元素是 { doOperations } 对象），
            // 需在 doOperations 中查找 insert 动作对应的新块 ID
            const newBlockId = insertResult[0]?.doOperations?.find(
              (op) => op.action === "insert",
            )?.id ?? insertResult[0]?.doOperations?.[0]?.id
            if (!newBlockId) {
              throw new Error("insertBlock 未返回新块 ID，追加内容可能未生效")
            }
            insertedBlockIds.push(newBlockId)
            prevId = newBlockId
          }
        }
      } else {
        const result = await api.updateBlock("markdown", siyuanContent, docId)
        if (!result) {
          throw new Error("updateBlock API 返回为空，更新可能未生效")
        }
      }

      // 保存编辑历史
      editHistoryStack.value.push({
        docId: editTargetDoc.value.id,
        docTitle: editTargetDoc.value.title,
        originalContent: originalContent.value,
        timestamp: Date.now(),
        isBlock: editTargetDoc.value.isBlock,
        insertedBlockIds: insertedBlockIds.length > 0 ? insertedBlockIds : undefined,
      })
      if (editHistoryStack.value.length > MAX_EDIT_HISTORY) {
        editHistoryStack.value.shift()
      }

      originalContent.value = generatedContent.value
      editTargetDoc.value.content = generatedContent.value
    } catch (error) {
      console.error("应用编辑失败:", error)
      showMessage("应用编辑失败: " + (error as Error).message, 3000, "error")
    } finally {
      isApplying.value = false
    }
  }

  /** 撤回编辑 */
  const undoEdit = async () => {
    if (editHistoryStack.value.length === 0) return

    isUndoing.value = true
    try {
      const lastHistory = editHistoryStack.value.pop()!
      const historyDocId = lastHistory.docId

      // 块模式下先删除追加的块
      if (lastHistory.isBlock && lastHistory.insertedBlockIds?.length) {
        for (const blockId of lastHistory.insertedBlockIds) {
          try { await api.deleteBlock(blockId) }
          catch (e) { console.warn("删除追加块失败，可能已被手动删除:", blockId, e) }
        }
      }

      const result = await api.updateBlock(
        "markdown", lastHistory.originalContent, historyDocId,
      )
      if (!result) {
        throw new Error("updateBlock API 返回为空，恢复可能未生效")
      }

      showMessage(`已撤回对文档的编辑: ${lastHistory.docTitle}`, 2000, "info")

      if (editTargetDoc.value && editTargetDoc.value.id === lastHistory.docId) {
        generatedContent.value = lastHistory.originalContent
        displayedContent.value = lastHistory.originalContent
        originalContent.value = lastHistory.originalContent
        editTargetDoc.value.content = lastHistory.originalContent
      }
    } catch (error) {
      console.error("撤回编辑失败:", error)
    } finally {
      isUndoing.value = false
    }
  }

  /** 插入子文档 */
  const insertSubDocument = async () => {
    if (!editTargetDoc.value || !generatedContent.value) {
      showMessage("请先选择文档并生成内容", 2000, "info")
      return
    }

    isInsertingSubDoc.value = true

    try {
      const parentDoc = await api.getBlockByID(editTargetDoc.value.id)
      if (!parentDoc || !parentDoc.box) {
        throw new Error("无法获取父文档信息")
      }

      // 父文档路径以文档 ID 解析：块模式下目标 ID 是块 ID，getHPathByID 对块 ID 无效
      // （返回空串导致子文档被创建到笔记本根目录）
      const parentDocId = editTargetDoc.value.isBlock
        ? parentDoc.root_id
        : editTargetDoc.value.id
      const parentDocHPath = await api.getHPathByID(parentDocId)
      if (!parentDocHPath) {
        throw new Error("无法获取父文档路径")
      }
      const parentDocName = parentDocHPath.split("/").pop() || "文档"
      const subDocTitle = `${parentDocName}总结`
      const timestamp = new Date().toLocaleDateString("zh-CN").replace(/\//g, "-")
      const finalSubDocTitle = `${subDocTitle}_${timestamp}`

      const siyuanContent = processContentByType(generatedContent.value, false)

      const subDocPath = `${parentDocHPath}/${finalSubDocTitle}`
      const subDocId = await api.createDocWithMd(parentDoc.box, subDocPath, siyuanContent)

      if (subDocId) {
        showMessage(
          `已在文档"${parentDoc.content || editTargetDoc.value.title}"下创建子文档: ${finalSubDocTitle}`,
          3000, "info",
        )
      } else {
        throw new Error("创建子文档失败")
      }
    } catch (error) {
      showMessage("插入子文档失败: " + (error as Error).message, 3000, "error")
    } finally {
      isInsertingSubDoc.value = false
    }
  }

  return {
    isApplying, isUndoing, isInsertingSubDoc,
    canUndoEdit,
    clearContent, clearTargetDocument,
    copyContent, applyEdit, undoEdit, insertSubDocument,
  }
}

/**
 * AI 内容生成管道 Composable
 * 封装流式生成、RAF 缓冲、对话历史、构建选项、执行封装
 */
import { ref, computed, type Ref, type ComputedRef } from "vue"
import { showMessage } from "siyuan"
import type { Plugin } from "siyuan"
import type { DeepSeekReasoningEffort, GenerateOptions, SearchResult, SkillItem, TargetDoc } from "@/types/ai"
import { PROVIDER_MODELS, DEEPSEEK_V4_MODEL_PREFIX } from "@/config/aiModels"

// ============ 类型定义 ============

interface ConversationTurn {
  role: "user" | "assistant"
  content: string
  timestamp: number
}

/** 硬编码的默认生成参数 */
const DEFAULT_TEMPERATURE = 0.7
const DEFAULT_MAX_TOKENS = 10000
/**
 * 思考模式专用输出预算：思考 token 与正文 token 共用 max_tokens，
 * 思考强度 high/max 时 10000 预算会被思考耗尽导致无正文。
 * 仅思考模式使用（思考开关限 deepseek-v4-*，该系列支持大预算，不影响其他供应商）
 */
const THINKING_MAX_TOKENS = 32000

interface UseGenerationOptions {
  enableThinking: Ref<boolean>
  reasoningEffort: Ref<DeepSeekReasoningEffort>
  webSearch: Ref<boolean>
  selectedModel: Ref<string>
  customModel: Ref<string>
  resolvedModel: ComputedRef<string>
  currentSkill: Ref<SkillItem | null>
  editTargetDoc: Ref<TargetDoc | null>
  editCustomInput: Ref<string>
  plugin: Plugin
  onGenerate: (options: GenerateOptions) => Promise<string>
  /** 生成完成后的审核回调（携带本次用户真实指令，供审核阶段理解需求） */
  onAfterGenerate?: (reviewUserRequest?: string) => void
}

/** executeGeneration 附加选项 */
export interface ExecuteGenerationOptions {
  /** 跳过自动审核（如自动修复内部循环） */
  skipReview?: boolean
  /** 本次用户真实指令（审核阶段优先使用，避免被 onSuccess 清空的输入兜底） */
  reviewUserRequest?: string
}

// ============ Composable ============

export function useGeneration(opts: UseGenerationOptions) {
  // ===== 生成状态 =====
  const generatedContent = ref("")   // 实时完整内容（逐 chunk 即时更新）
  const displayedContent = ref("")   // 打字机效果缓存（RAF 节流更新，用于渲染）
  const isGenerating = ref(false)
  const errorMessage = ref("")
  const generationElapsed = ref("")
  const generationTip = ref("")
  let generationStartTime: number | null = null
  const abortController = ref<AbortController | null>(null)

  // ===== 流式缓冲 =====
  let chunkBuffer = ""
  let rafId: number | null = null
  let streamingInCodeBlock = false
  let headingCount = 0
  /** 组件卸载后禁止再调度 RAF（cleanupRaf 与 handleStop 竞态时防回调重新排队） */
  let disposed = false

  // ===== 推理内容 =====
  const reasoningContent = ref("")
  const showReasoning = ref(false)
  let reasoningBuffer = ""

  // ===== 搜索 =====
  const searchStatus = ref("")
  const searchResults = ref<SearchResult[]>([])

  // ===== 多轮对话 =====
  const conversationHistory = ref<ConversationTurn[]>([])
  const MAX_CONVERSATION_TURNS = 20

  // ===== 模型 =====
  // 供应商以 ref 承载：plugin.settings 为非响应式对象，直接 computed 会在首评后永久缓存
  // （settings 异步加载，Dock 挂载时通常未就绪），须由调用方显式调用 refreshProvider() 驱动刷新
  const providerRef = ref<string>("tongyi")
  const refreshProvider = () => {
    providerRef.value = (opts.plugin as any)?.settings?.aiApiProvider || "tongyi"
  }
  const availableModels = computed(() => {
    return PROVIDER_MODELS[providerRef.value] || { common: [], all: [] }
  })
  const supportsThinking = computed(() =>
    providerRef.value === "deepseek"
    && opts.selectedModel.value.startsWith(DEEPSEEK_V4_MODEL_PREFIX),
  )

  // ===== 搜索稳定回调（避免每次 buildGenerateOptions 重新创建闭包） =====
  const stableSearchStart = () => {
    searchStatus.value = "正在搜索网络..."
  }
  const stableSearchResults = (results: SearchResult[]) => {
    searchResults.value = results
    searchStatus.value = `已获取 ${results.length} 条搜索结果`
  }
  const stableSearchError = (error: string) => {
    searchStatus.value = `搜索失败: ${error}`
    showMessage(`联网搜索失败: ${error}`, 3000, "info")
  }

  /** 思考截断自动重试前：清空旧思考展示（重试的思考是全新流，替换展示避免重复堆叠） */
  const stableTruncationRetry = () => {
    reasoningBuffer = ""
    reasoningContent.value = ""
    showReasoning.value = true
  }

  // ===== 内部辅助 =====

  /** 开始生成：初始化状态 */
  const startGeneration = () => {
    generationStartTime = performance.now()
    generationElapsed.value = ""
    abortController.value = new AbortController()
    isGenerating.value = true
    generatedContent.value = ""
    displayedContent.value = ""
    reasoningContent.value = ""
    showReasoning.value = true
    chunkBuffer = ""
    reasoningBuffer = ""
    streamingInCodeBlock = false
    headingCount = 0
    generationTip.value = ""
    if (rafId) {
      cancelAnimationFrame(rafId)
      rafId = null
    }
    errorMessage.value = ""
    searchStatus.value = ""
    searchResults.value = []
  }

  /** 重置生成相关状态（生成结束后调用） */
  const resetAllGenerationStates = () => {
    isGenerating.value = false
    abortController.value = null
  }

  /** 记录生成耗时并格式化显示 */
  const recordGenerationElapsed = () => {
    if (generationStartTime === null) return
    const elapsed = performance.now() - generationStartTime
    if (elapsed >= 1000) {
      generationElapsed.value = `${(elapsed / 1000).toFixed(1)}s`
    } else {
      generationElapsed.value = `${Math.round(elapsed)}ms`
    }
    generationStartTime = null
  }

  /** 处理生成错误，返回 true 表示用户取消 */
  const handleGenerationError = (
    error: Error,
    context: string,
    skipMessage = false,
  ): boolean => {
    if (error.name === "AbortError") return true
    console.error(`${context}失败:`, error)
    if (!skipMessage) {
      errorMessage.value = error.message || `${context}失败`
    }
    return false
  }

  /** RAF 刷新缓冲区 */
  const flushChunkBuffer = () => {
    if (chunkBuffer) {
      let codeBlockToggle = 0
      for (let i = 0; i < chunkBuffer.length; i++) {
        if (chunkBuffer.slice(i, i + 3) === "```") codeBlockToggle++
      }
      if (codeBlockToggle % 2 !== 0) {
        streamingInCodeBlock = !streamingInCodeBlock
      }
      const headingMatches = chunkBuffer.match(/^#{1,6}\s/gm)
      if (headingMatches) headingCount += headingMatches.length

      if (headingCount >= 2) {
        generationTip.value = `已生成 ${headingCount} 个章节`
      } else if (streamingInCodeBlock) {
        generationTip.value = "正在生成代码块..."
      } else {
        generationTip.value = ""
      }

      displayedContent.value += chunkBuffer
      chunkBuffer = ""
    }
    if (reasoningBuffer) {
      reasoningContent.value += reasoningBuffer
      reasoningBuffer = ""
    }
    rafId = null
  }

  /** 默认流式输出回调（即时更新 generatedContent，RAF 节流更新 displayedContent） */
  const defaultOnChunk = (chunk: string) => {
    if (disposed) return
    generatedContent.value += chunk
    chunkBuffer += chunk
    if (!rafId) {
      rafId = requestAnimationFrame(flushChunkBuffer)
    }
  }

  /** 思考过程回调 */
  const defaultOnReasoningChunk = (chunk: string) => {
    if (disposed) return
    reasoningBuffer += chunk
    if (!rafId) {
      rafId = requestAnimationFrame(flushChunkBuffer)
    }
  }

  // ===== 对话历史 =====

  const buildConversationContext = (): string => {
    if (conversationHistory.value.length === 0) return ""
    return conversationHistory.value
      .map((turn) => `[${turn.role === "user" ? "用户" : "助手"}]: ${turn.content}`)
      .join("\n\n")
  }

  /** 原子化添加对话轮次 */
  const addConversationTurns = (userInput: string) => {
    if (!generatedContent.value) return
    conversationHistory.value.push({
      role: "user",
      content: userInput.length > 500 ? userInput.slice(0, 500) + "..." : userInput,
      timestamp: Date.now(),
    })
    conversationHistory.value.push({
      role: "assistant",
      content: generatedContent.value.length > 300
        ? generatedContent.value.slice(0, 300) + "..."
        : generatedContent.value,
      timestamp: Date.now(),
    })
    if (conversationHistory.value.length > MAX_CONVERSATION_TURNS * 2) {
      conversationHistory.value = conversationHistory.value.slice(-MAX_CONVERSATION_TURNS * 2)
    }
  }

  const clearConversation = () => {
    conversationHistory.value = []
  }

  // ===== 选项构建 =====

  /** 构建 API 调用选项（稳定闭包引用） */
  const buildGenerateOptions = (
    userInput: string,
    systemPrompt: string,
    searchQueryOverride?: string,
  ): GenerateOptions => ({
    userInput,
    systemPrompt,
    temperature: DEFAULT_TEMPERATURE,
    maxTokens: opts.enableThinking.value ? THINKING_MAX_TOKENS : DEFAULT_MAX_TOKENS,
    signal: abortController.value?.signal,
    onChunk: defaultOnChunk,
    ...(opts.enableThinking.value
      ? { onReasoningChunk: defaultOnReasoningChunk, onTruncationRetry: stableTruncationRetry }
      : {}),
    model: opts.resolvedModel.value || undefined,
    enableThinking: opts.enableThinking.value,
    reasoningEffort: opts.reasoningEffort.value,
    webSearch: opts.webSearch.value,
    ...(searchQueryOverride ? { searchQuery: searchQueryOverride } : {}),
    onSearchStart: stableSearchStart,
    onSearchResults: stableSearchResults,
    onSearchError: stableSearchError,
    ...(conversationHistory.value.length > 0
      ? { context: buildConversationContext() }
      : {}),
  })

  // ===== 执行封装 =====

  const executeGeneration = async (
    context: string,
    buildOptions: () => GenerateOptions,
    onSuccess?: () => void,
    execOptions: ExecuteGenerationOptions = {},
  ) => {
    // 防重入：生成进行中忽略新的生成请求（Ctrl+Enter/连点快捷操作可绕过按钮禁用）
    if (isGenerating.value) return

    const { skipReview = false, reviewUserRequest } = execOptions
    let failed = false
    startGeneration()
    try {
      const options = buildOptions()
      const userInput = options.userInput
      await opts.onGenerate(options)
      // 用户主动停止（signal 中止）时流可能已返回部分内容：
      // 视为失败，不把半截内容写入对话历史、不触发审核
      if (options.signal?.aborted) {
        failed = true
        return
      }
      addConversationTurns(userInput)
      onSuccess?.()
    } catch (error) {
      // 中止/失败均标记 failed，避免对残缺内容触发审核
      failed = true
      if (handleGenerationError(error as Error, context)) return
    } finally {
      resetAllGenerationStates()
      recordGenerationElapsed()
      if (!failed && !skipReview) {
        opts.onAfterGenerate?.(reviewUserRequest)
      }
    }
  }

  /** 停止生成 */
  const handleStop = () => {
    if (abortController.value) {
      abortController.value.abort()
    }
    resetAllGenerationStates()
    generationElapsed.value = ""
    generationStartTime = null
  }

  /** 清理 RAF（供 onUnmounted 调用） */
  const cleanupRaf = () => {
    disposed = true
    if (rafId) {
      cancelAnimationFrame(rafId)
      rafId = null
    }
  }

  /** 清除生成展示态（推理/搜索/提示），供"清除"按钮组合调用，避免残留区块渲染 */
  const clearDisplayState = () => {
    reasoningContent.value = ""
    showReasoning.value = false
    searchStatus.value = ""
    searchResults.value = []
    generationTip.value = ""
    reasoningBuffer = ""
  }

  return {
    // 状态
    generatedContent,
    displayedContent,
    isGenerating,
    errorMessage,
    generationElapsed,
    generationTip,
    reasoningContent,
    showReasoning,
    searchStatus,
    searchResults,
    conversationHistory,
    // computed
    availableModels,
    supportsThinking,
    // 函数
    handleStop,
    cleanupRaf,
    buildGenerateOptions,
    executeGeneration,
    clearConversation,
    refreshProvider,
    clearDisplayState,
  }
}

/**
 * 审核系统 Composable
 * 封装审核状态、审核执行、自动修正和定向修复逻辑
 */
import { ref, type Ref } from "vue"
import { showMessage } from "siyuan"
import type { GenerateOptions, ReviewResult, SkillItem, TargetDoc } from "@/types/ai"
import type { ExecuteGenerationOptions } from "./useGeneration"
import { DEFAULT_SYSTEM_PROMPTS } from "../types"
import { buildSkillSystemPrompt } from "../utils"

// ============ 类型 ============

const MAX_AUTO_FIX_ITERATIONS = 2

export interface UseReviewDeps {
  /** 当前生成内容 */
  generatedContent: Ref<string>
  /** 当前技能 */
  currentSkill: Ref<SkillItem | null>
  /** 编辑目标文档 */
  editTargetDoc: Ref<TargetDoc | null>
  /** 自定义输入 */
  editCustomInput: Ref<string>
  /** 执行生成（来自 useGeneration） */
  executeGeneration: (
    context: string,
    buildOptions: () => GenerateOptions,
    onSuccess?: () => void,
    options?: ExecuteGenerationOptions,
  ) => Promise<void>
  /** 构建选项 */
  buildGenerateOptions: (userInput: string, systemPrompt: string, searchQueryOverride?: string) => GenerateOptions
  /** 外部审核回调 */
  onReview: (
    userRequest: string,
    generatedContent: string,
    skill?: SkillItem,
  ) => Promise<ReviewResult>
}

// ============ Composable ============

export function useReview(deps: UseReviewDeps) {
  const enableReview = ref(false)
  const isReviewing = ref(false)
  const reviewResult = ref<ReviewResult | null>(null)
  const isAutoFixing = ref(false)
  const autoFixCount = ref(0)

  const { generatedContent, currentSkill, editTargetDoc,
    editCustomInput, executeGeneration, buildGenerateOptions, onReview } = deps

  // ===== 审核逻辑 =====

  /**
   * 执行交叉审核
   * @param override 优先使用的用户需求描述（生成发起方传入的真实指令，避免被 onSuccess 清空的输入兜底）
   * @param force 强制审核：跳过 enableReview 开关检查，供"直接审查"按钮调用
   */
  const performReview = async (override?: string, force = false) => {
    if ((!enableReview.value && !force) || !generatedContent.value) return

    const userRequest = override
      || editCustomInput.value
      || (editTargetDoc.value ? `对文档"${editTargetDoc.value.title}"进行编辑` : "AI 内容生成")

    isReviewing.value = true
    reviewResult.value = null

    try {
      reviewResult.value = await onReview(
        userRequest,
        generatedContent.value,
        currentSkill.value || undefined,
      )
    } finally {
      // 无论成功/异常都复位审核态，避免 isReviewing 卡死导致 canApplyEdit 永久禁用
      isReviewing.value = false
    }
    // 新一轮审核完成，重置自动修复计数（上限按审核周期计）
    autoFixCount.value = 0
  }

  /**
   * 手动重新审核
   */
  const handleReReview = () => {
    if (!generatedContent.value) return
    // 重新审核语义上等同强制审核：首次经"直接审查"进入时 enableReview 可能为关
    performReview(undefined, true)
  }

  /**
   * 自动修正：根据审核结果修复生成内容
   */
  const handleAutoFix = async () => {
    if (!reviewResult.value || !generatedContent.value) return

    // 先判上限再自增：超限直接提示并返回，不重置计数也不改 isAutoFixing
    if (autoFixCount.value >= MAX_AUTO_FIX_ITERATIONS) {
      showMessage(`已达到自动修复次数上限（${MAX_AUTO_FIX_ITERATIONS}次）`, 3000, "info")
      return
    }
    autoFixCount.value++

    isAutoFixing.value = true
    const currentContent = generatedContent.value

    const issuesText = reviewResult.value.issues
      .map((issue) => `- [${issue.severity}] ${issue.description}`)
      .join("\n")
    const suggestionsText = reviewResult.value.suggestions.join("\n")

    const fixInstruction = `请修正以下内容中的问题：

问题清单：
${issuesText}

改进建议：
${suggestionsText}`

    const systemPrompt = buildSkillSystemPrompt(
      currentSkill.value,
      DEFAULT_SYSTEM_PROMPTS.fixByReview,
    )

    await executeGeneration(
      "内容修正",
      () => buildGenerateOptions(
        `${fixInstruction}\n\n待修正内容：\n${currentContent}`,
        systemPrompt,
      ),
      undefined,
      { skipReview: true }, // 自动修复内部循环，跳过审核避免死循环
    )
    // 无论成功/失败/中止，退出时复位修复态，避免卡死 canApplyEdit
    isAutoFixing.value = false
  }

  /**
   * 定向修复单个问题
   */
  const handleFixIssue = async (issueIndex: number) => {
    if (!reviewResult.value || !generatedContent.value) return
    const issue = reviewResult.value.issues[issueIndex]
    if (!issue) return

    isAutoFixing.value = true
    const currentContent = generatedContent.value

    // 修复指令仅基于 issue 自身信息：suggestions 与 issues 由 AI 独立返回，索引并不对齐，不能按下标取建议
    const fixInstruction = `请修复以下文档中的第 ${issueIndex + 1} 个问题。
仅修改相关内容，保持文档其他部分不变。

问题描述：${issue.description}
严重程度：${issue.severity}

直接输出修复后的完整文档。`

    const systemPrompt = buildSkillSystemPrompt(
      currentSkill.value,
      DEFAULT_SYSTEM_PROMPTS.fixIssue,
    )

    await executeGeneration(
      "定向修复",
      () => buildGenerateOptions(
        `${fixInstruction}\n\n当前文档：\n${currentContent}`,
        systemPrompt,
      ),
      undefined,
      { skipReview: true },
    )
    // 无论成功/失败/中止，退出时复位修复态，避免卡死 canApplyEdit
    isAutoFixing.value = false
  }

  /** 清除审核态（结果/修复状态），供"清除"按钮组合调用 */
  const clearReviewState = () => {
    reviewResult.value = null
    isAutoFixing.value = false
    autoFixCount.value = 0
  }

  return {
    enableReview, isReviewing, reviewResult, isAutoFixing,
    performReview, handleAutoFix, handleReReview, handleFixIssue,
    clearReviewState,
  }
}

